<template><div class="page"><header><h2>我的成绩</h2><p>仅展示教师已发布的本人课程成绩</p></header><p v-if="message" class="error">{{ message }}</p><section class="grid"><article v-for="s in sheets" :key="s.courseId"><div class="top"><div><small>{{ s.courseName }}</small><h3>{{ s.totalScore??'—' }}</h3><span>总评成绩</span></div><strong>{{ grade(s.totalScore) }}</strong></div><div v-for="i in s.items" :key="i.gradeItemId" class="row"><span>{{ i.itemName }} · 权重 {{ i.itemWeight }}%</span><b>{{ i.score??'—' }} / {{ i.fullScore }}</b><small v-if="i.comment">{{ i.comment }}</small></div></article><div v-if="!loading&&sheets.length===0" class="empty">暂无已发布成绩</div></section></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{getCoursePage,getMyCourseGrade,type StudentGradeSheet}from'../../utils/teachingApi';const sheets=ref<StudentGradeSheet[]>([]),loading=ref(false),message=ref('');const grade=(n?:number|null)=>n==null?'未评定':n>=90?'优秀':n>=80?'良好':n>=70?'中等':n>=60?'及格':'不及格';onMounted(async()=>{loading.value=true;try{const courses=(await getCoursePage({pageNum:1,pageSize:500})).records;const result=await Promise.all(courses.map(c=>getMyCourseGrade(c.courseId).catch(()=>null)));sheets.value=result.filter((x):x is StudentGradeSheet=>x!==null)}catch(e){message.value=e instanceof Error?e.message:'加载成绩失败'}finally{loading.value=false}});
</script><style scoped>.page{height:100%;overflow:auto;padding:28px 36px;background:transparent;color:#172033}header h2{margin:0}header p{color:#7b8495}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:18px}.grid article{padding:18px;background:#fff;border:1px solid #e7ebf1;border-radius:12px}.top{display:flex;justify-content:space-between;align-items:start;padding-bottom:14px;border-bottom:1px solid #eef1f5}.top small{color:#1d4ed8}.top h3{margin:6px 0 0;font-size:32px}.top span{font-size:12px;color:#7b8495}.top>strong{padding:5px 9px;border-radius:7px;background:#eff6ff;color:#1d4ed8}.row{display:grid;grid-template-columns:1fr auto;gap:5px;padding:11px 0;border-bottom:1px solid #eef1f5;font-size:13px}.row small{grid-column:1/-1;color:#7b8495}.empty{grid-column:1/-1;text-align:center;padding:60px;color:#8992a2}.error{color:#b42336}@media(max-width:750px){.grid{grid-template-columns:1fr}}</style>
